SELECT o.OrderID,o.CustomerID,o.BackorderOrderID,o.OrderDate,o.PickingCompletedWhen,ol.OrderLineID,ol.StockItemID,ol.Quantity,ol.PickedQuantity FROM Sales.Orders o LEFT JOIN Sales.OrderLines ol ON ol.OrderID=o.OrderID WHERE o.OrderID IN (73573,73595,73586) ORDER BY o.OrderID,ol.OrderLineID;
SELECT si.StockItemID,si.StockItemName,h.QuantityOnHand,COALESCE(d.UnpickedUnits,0) UnpickedUnits,COALESCE(i.IncomingPOs,0) IncomingPOs FROM Warehouse.StockItems si JOIN Warehouse.StockItemHoldings h ON h.StockItemID=si.StockItemID LEFT JOIN (SELECT StockItemID,SUM(CONVERT(bigint,Quantity)-PickedQuantity) UnpickedUnits FROM Sales.OrderLines WHERE PickedQuantity<Quantity GROUP BY StockItemID)d ON d.StockItemID=si.StockItemID LEFT JOIN (SELECT pl.StockItemID,COUNT(DISTINCT po.PurchaseOrderID) IncomingPOs FROM Purchasing.PurchaseOrderLines pl JOIN Purchasing.PurchaseOrders po ON po.PurchaseOrderID=pl.PurchaseOrderID WHERE po.IsOrderFinalized=0 AND pl.IsOrderLineFinalized=0 AND pl.OrderedOuters>pl.ReceivedOuters GROUP BY pl.StockItemID)i ON i.StockItemID=si.StockItemID WHERE si.StockItemID IN (2,80) ORDER BY si.StockItemID;
SELECT SUM((CONVERT(bigint,pl.OrderedOuters)-pl.ReceivedOuters)*si.QuantityPerOuter) IncomingUnits,COUNT_BIG(*) IncomingLines,COUNT(DISTINCT po.PurchaseOrderID) IncomingPOs FROM Purchasing.PurchaseOrderLines pl JOIN Purchasing.PurchaseOrders po ON po.PurchaseOrderID=pl.PurchaseOrderID JOIN Warehouse.StockItems si ON si.StockItemID=pl.StockItemID WHERE po.IsOrderFinalized=0 AND pl.IsOrderLineFinalized=0 AND pl.OrderedOuters>pl.ReceivedOuters;
SELECT COUNT_BIG(*) OrdersWithoutLines FROM Sales.Orders o WHERE NOT EXISTS (SELECT 1 FROM Sales.OrderLines ol WHERE ol.OrderID=o.OrderID);
SELECT COUNT_BIG(*) PostReferenceDeliveries FROM Sales.Invoices WHERE ConfirmedDeliveryTime>='20160601';
SELECT StockItemID,QuantityPerOuter,UnitPackageID,OuterPackageID,MIN(ValidFrom) FirstValid,MAX(ValidTo) LastValid,COUNT_BIG(*) Versions FROM Warehouse.StockItems FOR SYSTEM_TIME ALL WHERE StockItemID=80 GROUP BY StockItemID,QuantityPerOuter,UnitPackageID,OuterPackageID;
SELECT COUNT_BIG(*) InvoicesForDemo FROM Sales.Invoices WHERE OrderID=73595;
SELECT 'Sales.Customers' Entity,COUNT_BIG(*) Records FROM Sales.Customers UNION ALL SELECT 'Sales.Orders',COUNT_BIG(*) FROM Sales.Orders UNION ALL SELECT 'Sales.OrderLines',COUNT_BIG(*) FROM Sales.OrderLines UNION ALL SELECT 'Warehouse.StockItems',COUNT_BIG(*) FROM Warehouse.StockItems UNION ALL SELECT 'Warehouse.StockItemHoldings',COUNT_BIG(*) FROM Warehouse.StockItemHoldings UNION ALL SELECT 'Purchasing.PurchaseOrders',COUNT_BIG(*) FROM Purchasing.PurchaseOrders UNION ALL SELECT 'Purchasing.PurchaseOrderLines',COUNT_BIG(*) FROM Purchasing.PurchaseOrderLines UNION ALL SELECT 'Purchasing.Suppliers',COUNT_BIG(*) FROM Purchasing.Suppliers;

